import { supabaseAdmin } from "@/lib/supabaseAdmin";
import { createClient } from "@/lib/supabase";
import { unstable_cache } from "next/cache";

export interface ShopProduct {
    id: string;
    name: string;
    slug: string;
    description: string | null;
    price_ghs: number;
    compare_at_price_ghs: number | null;
    image_urls: string[] | null;
    is_featured: boolean;
    category_id: string | null;
    category_name: string | null;
    category_slug: string | null;
    available_colors: string[] | null;
    available_sizes: string[] | null;
    color_variants: Array<{ name: string; hex: string; in_stock: boolean }> | null;
    size_variants: Array<{ label: string; in_stock: boolean }> | null;
    bundle_label: string | null;
    badge: string | null;
    is_sale: boolean;
    discount_value: number;
    inventory_count: number;
    track_inventory: boolean;
    track_variant_inventory: boolean;
    preorder_enabled: boolean;
    preorder_estimated_date: string | null;
    category_ids: string[] | null;
    created_at: string;
}

export interface ShopCategory {
    id: string;
    name: string;
    slug: string;
    product_count: number;
    sort_order: number;
}

export interface GetProductsParams {
    category?: string | null;
    sort?: string | null;
    color?: string | null;
    size?: string | null;
    min?: string | null;
    max?: string | null;
    page?: number;
    q?: string | null;
    inStock?: boolean;
    sale?: boolean;
}

const PAGE_SIZE = 24;

// ── Cached categories fetch — reused across getProducts and getProductBySlug ──
const getCachedCategories = unstable_cache(
    async () => {
        const db = createClient();
        const { data } = await db.from("categories").select("id, name, slug, preorder_enabled, preorder_estimated_weeks");
        return (data ?? []) as Array<{ id: string; name: string; slug: string; preorder_enabled: boolean; preorder_estimated_weeks: number }>;
    },
    ["categories-name-map"],
    { revalidate: 300 }
);

const getCachedProducts = unstable_cache(
    async (params: GetProductsParams, role?: string) => {
        const { category, sort, color, size, min, max, page = 1, q, sale, inStock } = params;
        const db = createClient();

        const [catResult, minBoundResult, maxBoundResult, allCats] = await Promise.all([
            category
                ? db.from("categories").select("id, name").eq("slug", category).maybeSingle()
                : Promise.resolve({ data: null }),
            db.from("products").select("price_ghs").eq("is_active", true).order("price_ghs", { ascending: true }).limit(1),
            db.from("products").select("price_ghs").eq("is_active", true).order("price_ghs", { ascending: false }).limit(1),
            getCachedCategories(),
        ]);

        const minPrice = catResult !== null && minBoundResult.data?.[0]
            ? Math.floor(Number(minBoundResult.data[0].price_ghs))
            : 0;
        const maxPrice = maxBoundResult.data?.[0]
            ? Math.ceil(Number(maxBoundResult.data[0].price_ghs))
            : 1000;

        const catMap = new Map<string, { name: string; slug: string }>(
            allCats.map((c: any) => [c.name.toLowerCase(), c])
        );
        const preorderCatById = new Map(
            allCats.filter((c: any) => c.preorder_enabled).map((c: any) => [c.id, c])
        );
        const preorderCatByName = new Map(
            allCats.filter((c: any) => c.preorder_enabled).map((c: any) => [c.name.toLowerCase(), c])
        );

        let query = db
            .from("products")
            .select(
                `id, name, slug, description, price_ghs, compare_at_price_ghs,
                 image_urls, is_featured, is_active, category_id, category_type, category_ids,
                 available_colors, available_sizes, color_variants, size_variants,
                 bundle_label, badge, is_sale, discount_value, inventory_count, track_inventory, track_variant_inventory, preorder_enabled, preorder_estimated_date, sku, created_at`,
                { count: "exact" }
            );

        query = query.or("is_active.eq.true,is_active.is.null");

        if (category) {
            const cat = catResult.data as { id: string; name: string } | null;
            if (cat) {
                query = query.or(`category_id.eq.${cat.id},category_type.ilike."${cat.name}",category_ids.cs.{"${cat.id}"}`);
            } else {
                const fallbackName = category.split("-").map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(" ");
                query = query.ilike("category_type", fallbackName);
            }
        }

        if (q) query = query.or(`name.ilike.%${q}%,sku.ilike.%${q}%`);
        if (sale) query = query.eq("is_sale", true);
        if (inStock) query = query.gt("inventory_count", 0);
        if (min) query = query.gte("price_ghs", parseFloat(min));
        if (max) query = query.lte("price_ghs", parseFloat(max));
        if (color) query = query.contains("available_colors", [color]);
        if (size) query = query.contains("available_sizes", [size]);

        switch (sort) {
            case "price-asc":  query = query.order("price_ghs",  { ascending: true });  break;
            case "price-desc": query = query.order("price_ghs",  { ascending: false }); break;
            case "name-asc":   query = query.order("name",       { ascending: true });  break;
            default:           query = query.order("created_at", { ascending: false }); break;
        }

        const from = (page - 1) * 24; // Use constant or PAGE_SIZE
        query = query.range(from, from + 24 - 1);

        const { data, count, error } = await query;
        if (error) {
            // PGRST103: offset exceeds available rows (e.g. page=4 on an empty category)
            if ((error as any).code === "PGRST103") {
                return { products: [], total: 0, minPrice, maxPrice };
            }
            console.error("[getProducts] Supabase Error:", error);
        }

        const products: ShopProduct[] = (data || []).map((p: any) => {
            const matchedCat = p.category_type ? catMap.get(p.category_type.toLowerCase()) : null;

            // Category-level preorder inheritance: if the product hasn't explicitly enabled
            // preorder, check if any of its assigned categories has preorder enabled
            let effectivePreorder = p.preorder_enabled ?? false;
            let effectivePreorderDate: string | null = p.preorder_estimated_date ?? null;
            if (!effectivePreorder) {
                const inheritedCat =
                    (p.category_ids as string[] | null)?.map((id: string) => preorderCatById.get(id)).find(Boolean)
                    ?? (p.category_id ? preorderCatById.get(p.category_id) : undefined)
                    ?? (p.category_type ? preorderCatByName.get(p.category_type.toLowerCase()) : undefined);
                if (inheritedCat) {
                    effectivePreorder = true;
                    if (!effectivePreorderDate && inheritedCat.preorder_estimated_weeks > 0) {
                        effectivePreorderDate = new Date(
                            Date.now() + inheritedCat.preorder_estimated_weeks * 7 * 24 * 60 * 60 * 1000
                        ).toISOString().split("T")[0];
                    }
                }
            }

            return {
                ...p,
                category_name: matchedCat?.name ?? p.category_type ?? null,
                category_slug: matchedCat?.slug ?? null,
                track_inventory: p.track_inventory ?? true,
                track_variant_inventory: p.track_variant_inventory ?? false,
                preorder_enabled: effectivePreorder,
                preorder_estimated_date: effectivePreorderDate,
            };
        });

        return { products, total: count ?? 0, minPrice, maxPrice };
    },
    ["products-list"],
    { revalidate: false, tags: ["products"] }
);

export async function getProducts(params: GetProductsParams, role?: string) {
    return getCachedProducts(params, role);
}

const getCachedCategoriesByRole = unstable_cache(
    async (isAuthorized: boolean) => {
        const db = createClient();
        let query = db
            .from("categories")
            .select("id, name, slug, product_count, sort_order")
            .eq("is_active", true);

        // Hide wholesale-only categories from retail users
        if (!isAuthorized) {
            query = query.or("is_wholesale.eq.false,is_wholesale.is.null");
        }

        const { data, error } = await query
            .order("sort_order", { ascending: true })
            .order("name",       { ascending: true });
            
        if (error) console.error("[getCategories]", error);
        return (data ?? []) as ShopCategory[];
    },
    ["categories-list"],
    { revalidate: 300 }
);

export async function getCategories(role?: string): Promise<ShopCategory[]> {
    const isAuthorized = !!role && ["admin", "owner", "wholesale", "wholesaler"].includes(role.toLowerCase());
    return getCachedCategoriesByRole(isAuthorized);
}

// Lightweight cached fetch of category assignments for all active products.
// Used to filter the storefront category list to only those with live products.
const getCachedProductCategoryAssignments = unstable_cache(
    async () => {
        const db = createClient();
        const { data } = await db
            .from("products")
            .select("category_id, category_type, category_ids")
            .eq("is_active", true);
        return (data ?? []) as Array<{ category_id: string | null; category_type: string | null; category_ids: string[] | null }>;
    },
    ["product-category-assignments"],
    { revalidate: 300, tags: ["products"] }
);

export async function getPopulatedCategoryFilter(allCategories: ShopCategory[]): Promise<ShopCategory[]> {
    const assignments = await getCachedProductCategoryAssignments();
    const activeCatIds = new Set(assignments.flatMap(p => p.category_ids ?? (p.category_id ? [p.category_id] : [])));
    const activeCatNames = new Set(assignments.map(p => (p.category_type ?? "").toLowerCase().trim()).filter(Boolean));
    return allCategories.filter(c =>
        activeCatIds.has(c.id) || activeCatNames.has(c.name.toLowerCase().trim())
    );
}

// ─── PDP interfaces ────────────────────────────────────────────────────────

export interface ProductDetail extends ShopProduct {
    category_type: string | null;
    sku: string | null;
    features_list: string[] | null;
    care_instructions: string[] | null;
    rating_average: number;
    review_count: number;
    wholesale_override?: boolean;
    wholesale_price_tier_1?: number | null;
    wholesale_price_tier_2?: number | null;
    wholesale_price_tier_3?: number | null;
}

export interface ProductReview {
    id: string;
    rating: number;
    comment: string | null;
    author_name: string | null;
    author_initials: string | null;
    avatar_color: string | null;
    location: string | null;
    is_verified: boolean;
    created_at: string;
}

export interface RatingDistribution {
    star: number;
    count: number;
    pct: number;
}

export async function getProductBySlug(slug: string): Promise<ProductDetail | null> {
    const { data, error } = await supabaseAdmin
        .from("products")
        .select(`id, name, slug, description, price_ghs, compare_at_price_ghs,
             image_urls, is_featured, category_type, category_ids,
             available_colors, available_sizes, color_variants, size_variants,
             bundle_label, badge, is_sale, discount_value, inventory_count, track_inventory, track_variant_inventory, preorder_enabled,
             sku, features_list, care_instructions, rating_average, review_count, created_at,
             wholesale_override, wholesale_price_tier_1, wholesale_price_tier_2, wholesale_price_tier_3`)
        .eq("slug", slug)
        .or("is_active.eq.true,is_active.is.null")
        .maybeSingle();

    if (error) {
        // PGRST002: transient PostgREST schema cache reload — retry once.
        if ((error as any).code === "PGRST002") {
            await new Promise(r => setTimeout(r, 500));
            return getProductBySlug(slug);
        }
        // Transient gateway error (Supabase/Cloudflare 502/503 during Vercel build or at runtime).
        // The Supabase JS client surfaces these as an error whose message contains raw HTML.
        // Throwing here crashes the SSG build worker for every product; returning null lets the
        // page call notFound() gracefully and ISR will rehydrate on the next request.
        const msg = String((error as any)?.message ?? "");
        if (msg.includes("<!DOCTYPE") || msg.includes("Bad gateway") || msg.includes("502") || msg.includes("503")) {
            console.warn("[getProductBySlug] Transient gateway error for slug:", slug, "— skipping pre-render");
            return null;
        }
        console.error("[getProductBySlug]", error);
        throw error;
    }
    if (!data) return null;

    // PERF-03: use cached categories — avoids a per-PDP round-trip
    const allCats = await getCachedCategories();
    const catMap = new Map<string, { name: string; slug: string }>(
        allCats.map((c: any) => [c.name.toLowerCase(), c])
    );
    const matchedCat = data.category_type ? catMap.get(data.category_type.toLowerCase()) : null;

    return {
        ...data,
        category_id: null,
        is_featured: data.is_featured ?? false,
        is_sale: data.is_sale ?? false,
        discount_value: data.discount_value ?? 0,
        inventory_count: data.inventory_count ?? 0,
        track_inventory: data.track_inventory ?? true,
        track_variant_inventory: data.track_variant_inventory ?? false,
        preorder_enabled: data.preorder_enabled ?? false,
        rating_average: Number(data.rating_average ?? 0),
        review_count: Number(data.review_count ?? 0),
        category_name: matchedCat?.name ?? data.category_type ?? null,
        category_slug: matchedCat?.slug ?? null,
    } as ProductDetail;
}

export async function getRelatedProducts(categoryType: string, currentSlug: string): Promise<ShopProduct[]> {
    if (!categoryType) return [];
    const db = createClient();
    const { data, error } = await db
        .from("products")
        .select(`id, name, slug, description, price_ghs, compare_at_price_ghs,
             image_urls, is_featured, category_type, category_ids,
             available_colors, available_sizes, color_variants, size_variants,
             bundle_label, badge, is_sale, discount_value, inventory_count, track_inventory, track_variant_inventory, created_at`)
        .eq("is_active", true)
        .ilike("category_type", categoryType)
        .neq("slug", currentSlug)
        .order("created_at", { ascending: false })
        .limit(4);
    if (error) console.error("[getRelatedProducts]", error);

    return (data || []).map((p: any) => ({
        ...p,
        category_id: null,
        is_featured: p.is_featured ?? false,
        is_sale: p.is_sale ?? false,
        track_inventory: p.track_inventory ?? true,
        track_variant_inventory: p.track_variant_inventory ?? false,
        discount_value: p.discount_value ?? 0,
        inventory_count: p.inventory_count ?? 0,
        category_name: p.category_type ?? null,
        category_slug: null,
    }));
}

export async function getProductReviews(productId: string): Promise<{
    reviews: ProductReview[];
    distribution: RatingDistribution[];
}> {
    const db = createClient();
    const { data, error } = await db
        .from("product_reviews")
        .select("id, rating, comment, author_name, author_initials, avatar_color, location, is_verified, created_at")
        .eq("product_id", productId)
        .order("created_at", { ascending: false })
        .limit(50);
    if (error) console.error("[getProductReviews]", error);

    const all = (data || []) as ProductReview[];
    const total = all.length;
    const distribution: RatingDistribution[] = [5, 4, 3, 2, 1].map(star => {
        const count = all.filter(r => r.rating === star).length;
        return { star, count, pct: total > 0 ? Math.round((count / total) * 100) : 0 };
    });

    return { reviews: all, distribution };
}

/** Derive all unique color names from a product list. */
export function deriveColors(products: ShopProduct[]): string[] {
    const set = new Set<string>();
    products.forEach(p => (p.available_colors ?? []).forEach(c => set.add(c)));
    return Array.from(set).sort();
}

/** Derive all unique size labels from a product list. */
export function deriveSizes(products: ShopProduct[]): string[] {
    const order = ["XS", "S", "M", "L", "XL", "2XL", "3XL", "Free", "6-10"];
    const set = new Set<string>();
    products.forEach(p => (p.available_sizes ?? []).forEach(s => set.add(s)));
    const sorted = Array.from(set);
    sorted.sort((a, b) => {
        const ai = order.indexOf(a);
        const bi = order.indexOf(b);
        if (ai === -1 && bi === -1) return a.localeCompare(b);
        if (ai === -1) return 1;
        if (bi === -1) return -1;
        return ai - bi;
    });
    return sorted;
}
/** Number of product rows fetched per page. Videos are a subset of this. */
export const VIDEO_BATCH_SIZE = 20;

// ── Static generation helper ───────────────────────────────────────────────
// Used by generateStaticParams to pre-build all active product pages at deploy
// time. Returns [] on error so builds don't hang if DB is slow.
export async function getAllProductSlugs(): Promise<string[]> {
    try {
        const { data } = await supabaseAdmin
            .from("products")
            .select("slug")
            .or("is_active.eq.true,is_active.is.null")
            .order("created_at", { ascending: false });
        return (data ?? []).map((p: { slug: string }) => p.slug).filter(Boolean);
    } catch {
        return [];
    }
}

export type VideoProduct = ShopProduct & { video_url: string };

// Return sizes from available_sizes whose label matches an in_stock size_variant.
// available_sizes entries look like "S — 8" or "Free Size"; size_variant labels are "S" / "Free Size".
// If no size_variants data exists, all sizes are returned unchanged.
function getInStockSizes(
    sizes: string[] | null,
    sizeVariants: { label: string; in_stock: boolean }[] | null
): string[] | null {
    if (!sizes) return sizes;
    if (!sizeVariants || sizeVariants.length === 0) return sizes;
    const inStock = new Set(sizeVariants.filter(v => v.in_stock).map(v => v.label));
    if (inStock.size === 0) return [];
    return sizes.filter(s => inStock.has(s.split(" — ")[0]));
}

// Same for colors: available_colors are plain names e.g. "Black", color_variant.name matches.
function getInStockColors(
    colors: string[] | null,
    colorVariants: { name: string; in_stock: boolean }[] | null
): string[] | null {
    if (!colors) return colors;
    if (!colorVariants || colorVariants.length === 0) return colors;
    const inStock = new Set(colorVariants.filter(v => v.in_stock).map(v => v.name));
    if (inStock.size === 0) return [];
    return colors.filter(c => inStock.has(c));
}

export async function getVideoProducts(offset = 0): Promise<{
    videos: VideoProduct[];
    nextOffset: number;
    hasMore: boolean;
}> {
    const db = createClient();
    const { data } = await db
        .from("products")
        .select(`id, name, slug, description, price_ghs, compare_at_price_ghs,
             image_urls, is_featured, category_type, category_ids,
             available_colors, available_sizes, color_variants, size_variants,
             bundle_label, badge, is_sale, discount_value, inventory_count, track_inventory, track_variant_inventory, created_at`)
        .eq("is_active", true)
        // Exclude products that track inventory and have none left
        .or("track_inventory.eq.false,inventory_count.gt.0")
        .order("created_at", { ascending: false })
        .range(offset, offset + VIDEO_BATCH_SIZE - 1);

    if (!data) return { videos: [], nextOffset: offset + VIDEO_BATCH_SIZE, hasMore: false };

    const videos = (data as any[])
        .map(p => {
            const video_url = p.image_urls?.find((url: string) =>
                url.toLowerCase().endsWith(".mp4") || url.toLowerCase().endsWith(".mov")
            ) as string | undefined;
            return {
                ...p,
                // Only expose in-stock sizes and colors so the QuickView modal only offers what's available
                available_sizes: getInStockSizes(p.available_sizes, p.size_variants),
                available_colors: getInStockColors(p.available_colors, p.color_variants),
                category_id: null,
                is_featured: p.is_featured ?? false,
                is_sale: p.is_sale ?? false,
                discount_value: p.discount_value ?? 0,
                inventory_count: p.inventory_count ?? 0,
                track_inventory: p.track_inventory ?? true,
                track_variant_inventory: p.track_variant_inventory ?? false,
                category_name: p.category_type ?? null,
                category_slug: null,
                video_url,
            };
        })
        .filter((p): p is VideoProduct => !!p.video_url);

    return {
        videos,
        nextOffset: offset + VIDEO_BATCH_SIZE,
        // If the DB returned a full batch, there may be more products to scan
        hasMore: data.length === VIDEO_BATCH_SIZE,
    };
}
